import { useState, useEffect, useCallback } from "react";
import { useParams, useNavigate } from "react-router-dom";
import { ArrowLeft, User, Mail, Clock, MessageSquare, Send, Sparkles, Loader2, Frown, Meh, Smile, TrendingDown, AlertTriangle, TrendingUp, RefreshCw, Wand2, History, MailOpen } from "lucide-react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Textarea } from "@/components/ui/textarea";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Input } from "@/components/ui/input";
import { Separator } from "@/components/ui/separator";
import { ScrollArea } from "@/components/ui/scroll-area";
import { Switch } from "@/components/ui/switch";
import { Label } from "@/components/ui/label";
import { Sheet, SheetContent, SheetHeader, SheetTitle, SheetTrigger } from "@/components/ui/sheet";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/hooks/useAuth";
import { useTicketCollaboration } from "@/hooks/useTicketCollaboration";
import { toast } from "sonner";
import { format } from "date-fns";
import { cn } from "@/lib/utils";
import { UserSupportActivity } from "@/components/admin/UserSupportActivity";
import { InternalNotesPanel, TicketAssignment } from "@/components/admin/support";

interface Ticket {
  id: string;
  subject: string;
  description: string;
  category: string;
  status: string;
  priority: string;
  sentiment: string | null;
  urgency: string | null;
  sentiment_override: boolean;
  urgency_override: boolean;
  created_at: string;
  user_id: string | null;
  guest_email: string | null;
  conversation_id: string | null;
  assigned_to: string | null;
  resolved_at: string | null;
  inbound_email: string | null;
  email_thread_id: string | null;
}

interface TicketResponse {
  id: string;
  content: string;
  is_internal: boolean;
  is_ai_draft?: boolean;
  source?: 'admin' | 'user' | 'email';
  email_message_id?: string | null;
  created_at: string;
  user_id?: string | null;
  admin_profile?: {
    display_name: string | null;
    email: string | null;
  } | null;
}

interface ConversationMessage {
  id: string;
  role: string;
  content: string;
  created_at: string;
  metadata?: Record<string, unknown>;
}

const STATUS_OPTIONS = [
  { value: "open", label: "Open" },
  { value: "in_progress", label: "In Progress" },
  { value: "resolved", label: "Resolved" },
  { value: "closed", label: "Closed" },
];

const PRIORITY_OPTIONS = [
  { value: "low", label: "Low" },
  { value: "normal", label: "Normal" },
  { value: "high", label: "High" },
  { value: "urgent", label: "Urgent" },
];

const SENTIMENT_OPTIONS = [
  { value: "positive", label: "Positive", icon: Smile, color: "text-green-600" },
  { value: "neutral", label: "Neutral", icon: Meh, color: "text-muted-foreground" },
  { value: "negative", label: "Negative", icon: Frown, color: "text-red-500" },
];

const URGENCY_OPTIONS = [
  { value: "low", label: "Low", icon: TrendingDown, color: "text-green-600" },
  { value: "medium", label: "Medium", icon: AlertTriangle, color: "text-amber-500" },
  { value: "high", label: "High", icon: TrendingUp, color: "text-red-500" },
];

export default function AdminTicketDetail() {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const { user } = useAuth();
  
  // Collaboration hook for assignments, notes, mentions
  const {
    internalNotes,
    collaborators,
    teamMembers,
    assignee,
    isAssigning,
    isAddingNote,
    assignTicket,
    addInternalNote,
    deleteNote,
    parseMentions,
  } = useTicketCollaboration(id);
  
  const [ticket, setTicket] = useState<Ticket | null>(null);
  const [responses, setResponses] = useState<TicketResponse[]>([]);
  const [conversationMessages, setConversationMessages] = useState<ConversationMessage[]>([]);
  const [userProfile, setUserProfile] = useState<{ display_name: string | null; email: string | null } | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [newResponse, setNewResponse] = useState("");
  const [isInternal, setIsInternal] = useState(false);
  const [isSending, setIsSending] = useState(false);
  const [isGeneratingDraft, setIsGeneratingDraft] = useState(false);
  const [isEditingWithAI, setIsEditingWithAI] = useState(false);
  const [aiEditInstructions, setAiEditInstructions] = useState("");
  const [showAiEdit, setShowAiEdit] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [hasAutoGenerated, setHasAutoGenerated] = useState(false);
  const [showUserHistory, setShowUserHistory] = useState(false);

  const fetchTicket = useCallback(async () => {
    if (!id) return;

    try {
      // Fetch ticket
      const { data: ticketData, error: ticketError } = await supabase
        .from("support_tickets")
        .select("*")
        .eq("id", id)
        .single();

      if (ticketError) throw ticketError;
      setTicket(ticketData);

      // Fetch user profile if this ticket belongs to a user
      if (ticketData?.user_id) {
        const { data: profile } = await supabase
          .from("profiles")
          .select("display_name, email")
          .eq("user_id", ticketData.user_id)
          .single();
        setUserProfile(profile);
      }

      // Fetch responses from support_ticket_responses table
      const { data: responseData } = await supabase
        .from("support_ticket_responses")
        .select("*")
        .eq("ticket_id", id)
        .order("created_at", { ascending: true });

      // Fetch admin/user profiles for responses
      if (responseData && responseData.length > 0) {
        const userIds = [...new Set(responseData.map(r => r.user_id).filter(Boolean))];
        let profileMap = new Map();
        if (userIds.length > 0) {
          const { data: profiles } = await supabase
            .from("profiles")
            .select("user_id, display_name, email")
            .in("user_id", userIds);
          profileMap = new Map(profiles?.map(p => [p.user_id, p]) || []);
        }
        const responsesWithProfiles = responseData.map(r => ({
          ...r,
          admin_profile: r.user_id ? profileMap.get(r.user_id) || null : null,
        }));
        setResponses(responsesWithProfiles as TicketResponse[]);
      } else {
        setResponses([]);
      }

      // Fetch conversation messages if available
      let convMessages: ConversationMessage[] = [];
      if (ticketData?.conversation_id) {
        const { data: messageData } = await supabase
          .from("support_messages")
          .select("id, role, content, created_at, metadata")
          .eq("conversation_id", ticketData.conversation_id)
          .order("created_at", { ascending: true });

        convMessages = messageData || [];
        setConversationMessages(convMessages);
      }

      // Return data for auto-draft decision
      return {
        ticket: ticketData,
        responses: responseData || [],
        conversationMessages: convMessages
      };
    } catch (err) {
      console.error("Failed to fetch ticket:", err);
      toast.error("Failed to load ticket");
      return null;
    } finally {
      setIsLoading(false);
    }
  }, [id]);

  // Auto-generate draft for new tickets (no responses yet) unless from negative feedback
  useEffect(() => {
    const initializeTicket = async () => {
      const result = await fetchTicket();
      if (!result || hasAutoGenerated) return;

      const { responses: ticketResponses, conversationMessages: convMsgs } = result;

      // Only auto-draft if no responses yet
      if (ticketResponses.length > 0) return;

      // Check if ticket came from negative feedback (user was unhappy with chatbot)
      const hasNegativeFeedback = convMsgs.some(
        (msg) => msg.metadata?.type === "feedback" && msg.metadata?.value === "negative"
      );

      // Skip auto-draft if user gave negative feedback (needs more careful human attention)
      if (hasNegativeFeedback) {
        console.log("Skipping auto-draft: ticket from negative chatbot feedback");
        return;
      }

      // Auto-generate draft
      setHasAutoGenerated(true);
      generateAIDraft();
    };

    initializeTicket();
  }, [id, fetchTicket, generateAIDraft, hasAutoGenerated]);

  const updateTicket = async (updates: Partial<Ticket>) => {
    if (!id) return;

    try {
      const { error } = await supabase
        .from("support_tickets")
        .update(updates)
        .eq("id", id);

      if (error) throw error;
      setTicket(prev => prev ? { ...prev, ...updates } : null);
      toast.success("Ticket updated");
    } catch (err) {
      console.error("Failed to update ticket:", err);
      toast.error("Failed to update ticket");
    }
  };

  const sendResponse = async () => {
    if (!id || !user || !newResponse.trim()) return;

    setIsSending(true);
    try {
      const { data: responseData, error } = await supabase
        .from("support_ticket_responses")
        .insert({
          ticket_id: id,
          user_id: user.id,
          content: newResponse.trim(),
          is_internal: isInternal,
          source: 'admin',
        })
        .select()
        .single();

      if (error) throw error;

      // Send email notification for non-internal responses
      if (!isInternal && responseData) {
        try {
          await supabase.functions.invoke("send-ticket-response-email", {
            body: {
              ticketId: id,
              responseId: responseData.id,
              responseContent: newResponse.trim(),
              baseUrl: window.location.origin,
            },
          });
        } catch (emailErr) {
          console.error("Failed to send email notification:", emailErr);
          // Don't fail the whole operation if email fails
        }
      }

      setNewResponse("");
      setIsInternal(false);
      fetchTicket();
      toast.success(isInternal ? "Internal note added" : "Response sent & email notification sent");
    } catch (err) {
      console.error("Failed to send response:", err);
      toast.error("Failed to send response");
    } finally {
      setIsSending(false);
    }
  };

  const generateAIDraft = useCallback(async () => {
    if (!id) return;

    setIsGeneratingDraft(true);
    try {
      const { data, error } = await supabase.functions.invoke('ticket-ai-draft', {
        body: { ticketId: id, action: 'draft', baseUrl: window.location.origin }
      });

      if (error) throw error;

      if (data?.draft) {
        setNewResponse(data.draft);
        setShowAiEdit(true);
        toast.success("Draft generated! Review and edit before sending.");
      } else if (data?.error) {
        toast.error(data.error);
      }
    } catch (err) {
      console.error("Failed to generate draft:", err);
      toast.error("Failed to generate AI draft");
    } finally {
      setIsGeneratingDraft(false);
    }
  }, [id]);

  const editWithAI = async () => {
    if (!id || !newResponse.trim() || !aiEditInstructions.trim()) return;

    setIsEditingWithAI(true);
    try {
      const { data, error } = await supabase.functions.invoke('ticket-ai-draft', {
        body: { 
          ticketId: id, 
          action: 'edit',
          currentDraft: newResponse,
          editInstructions: aiEditInstructions
        }
      });

      if (error) throw error;

      if (data?.draft) {
        setNewResponse(data.draft);
        setAiEditInstructions("");
        toast.success("Draft updated!");
      } else if (data?.error) {
        toast.error(data.error);
      }
    } catch (err) {
      console.error("Failed to edit draft:", err);
      toast.error("Failed to edit with AI");
    } finally {
      setIsEditingWithAI(false);
    }
  };

  const analyzeTicket = async () => {
    if (!id) return;

    setIsAnalyzing(true);
    try {
      const { data, error } = await supabase.functions.invoke('ticket-ai-draft', {
        body: { ticketId: id, action: 'analyze' }
      });

      if (error) throw error;

      if (data?.sentiment && data?.urgency) {
        await updateTicket({
          sentiment: data.sentiment,
          urgency: data.urgency,
          sentiment_override: false,
          urgency_override: false,
        });
        toast.success(`Analysis complete: ${data.sentiment} sentiment, ${data.urgency} urgency`);
      } else if (data?.error) {
        toast.error(data.error);
      }
    } catch (err) {
      console.error("Failed to analyze ticket:", err);
      toast.error("Failed to analyze ticket");
    } finally {
      setIsAnalyzing(false);
    }
  };

  if (isLoading) {
    return (
      <div className="flex items-center justify-center h-64">
        <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-primary"></div>
      </div>
    );
  }

  if (!ticket) {
    return (
      <div className="text-center py-12">
        <p className="text-muted-foreground">Ticket not found</p>
        <Button variant="link" onClick={() => navigate("/admin/support")}>
          Back to Support
        </Button>
      </div>
    );
  }

  const currentSentiment = SENTIMENT_OPTIONS.find(s => s.value === ticket.sentiment);
  const currentUrgency = URGENCY_OPTIONS.find(u => u.value === ticket.urgency);

  return (
    <div className="space-y-6">
      <div className="flex items-center gap-4">
        <Button variant="ghost" size="sm" onClick={() => navigate("/admin/support")}>
          <ArrowLeft className="h-4 w-4 mr-2" />
          Back
        </Button>
        <div className="flex-1">
          <h1 className="text-xl sm:text-2xl font-bold">{ticket.subject}</h1>
          <div className="flex items-center gap-2 mt-1 text-sm text-muted-foreground flex-wrap">
            <Badge variant="outline">{ticket.category}</Badge>
            <span>•</span>
            <span>{format(new Date(ticket.created_at), "MMM d, yyyy 'at' h:mm a")}</span>
          </div>
        </div>
      </div>

      <div className="grid gap-6 lg:grid-cols-3">
        {/* Main Content */}
        <div className="lg:col-span-2 space-y-6">
          {/* Original Description */}
          <Card>
            <CardHeader>
              <CardTitle className="text-sm font-medium">Original Request</CardTitle>
            </CardHeader>
            <CardContent>
              <div className="whitespace-pre-wrap text-sm">{ticket.description}</div>
            </CardContent>
          </Card>

          {/* Conversation History */}
          {conversationMessages.length > 0 && (
            <Card>
              <CardHeader>
                <CardTitle className="text-sm font-medium flex items-center gap-2">
                  <MessageSquare className="h-4 w-4" />
                  Chat History
                </CardTitle>
              </CardHeader>
              <CardContent>
                <ScrollArea className="h-[300px] pr-4">
                  <div className="space-y-3">
                    {conversationMessages.map((msg) => (
                      <div
                        key={msg.id}
                        className={`p-3 rounded-lg ${
                          msg.role === "user"
                            ? "bg-primary/10 ml-8"
                            : "bg-muted mr-8"
                        }`}
                      >
                        <div className="flex items-center gap-2 mb-1">
                          <Badge variant="outline" className="text-xs">
                            {msg.role === "user" ? "User" : "Assistant"}
                          </Badge>
                          <span className="text-xs text-muted-foreground">
                            {format(new Date(msg.created_at), "h:mm a")}
                          </span>
                        </div>
                        <p className="text-sm whitespace-pre-wrap">{msg.content}</p>
                      </div>
                    ))}
                  </div>
                </ScrollArea>
              </CardContent>
            </Card>
          )}

          {/* Responses */}
          <Card>
            <CardHeader>
              <CardTitle className="text-sm font-medium">Responses</CardTitle>
            </CardHeader>
            <CardContent className="space-y-4">
              {responses.length === 0 ? (
                <p className="text-sm text-muted-foreground text-center py-4">
                  No responses yet
                </p>
              ) : (
                responses.map((response) => (
                  <div
                    key={response.id}
                    className={cn(
                      "p-4 rounded-lg",
                      response.is_internal
                        ? "bg-amber-50 dark:bg-amber-950 border border-amber-200 dark:border-amber-800"
                        : response.source === 'email'
                        ? "bg-blue-50 dark:bg-blue-950 border border-blue-200 dark:border-blue-800"
                        : response.source === 'user'
                        ? "bg-primary/10 ml-8"
                        : "bg-muted"
                    )}
                  >
                    <div className="flex items-center gap-2 mb-2 flex-wrap">
                      <span className="text-sm font-medium">
                        {response.source === 'user' 
                          ? userProfile?.display_name || "User" 
                          : response.source === 'email'
                          ? "Via Email"
                          : response.admin_profile?.display_name || "Admin"}
                      </span>
                      {response.is_internal && (
                        <Badge variant="outline" className="text-xs bg-amber-100 dark:bg-amber-900">
                          Internal Note
                        </Badge>
                      )}
                      {response.source === 'email' && (
                        <Badge variant="outline" className="text-xs bg-blue-100 dark:bg-blue-900">
                          <MailOpen className="h-3 w-3 mr-1" />
                          Email
                        </Badge>
                      )}
                      {response.is_ai_draft && (
                        <Badge variant="outline" className="text-xs">
                          <Sparkles className="h-3 w-3 mr-1" />
                          AI Draft
                        </Badge>
                      )}
                      <span className="text-xs text-muted-foreground ml-auto">
                        {format(new Date(response.created_at), "MMM d 'at' h:mm a")}
                      </span>
                    </div>
                    <p className="text-sm whitespace-pre-wrap">{response.content}</p>
                  </div>
                ))
              )}

              <Separator />

              {/* New Response */}
              <div className="space-y-3">
                <div className="flex items-center justify-between">
                  <Label className="text-sm font-medium">New Response</Label>
                  <Button
                    variant="outline"
                    size="sm"
                    onClick={generateAIDraft}
                    disabled={isGeneratingDraft}
                  >
                    {isGeneratingDraft ? (
                      <Loader2 className="h-4 w-4 mr-2 animate-spin" />
                    ) : (
                      <Sparkles className="h-4 w-4 mr-2" />
                    )}
                    AI Draft
                  </Button>
                </div>
                <Textarea
                  placeholder="Write a response..."
                  value={newResponse}
                  onChange={(e) => {
                    setNewResponse(e.target.value);
                    if (!e.target.value.trim()) setShowAiEdit(false);
                  }}
                  rows={4}
                />
                
                {/* AI Edit Section - shown after draft is generated */}
                {showAiEdit && newResponse.trim() && (
                  <div className="flex gap-2">
                    <Input
                      placeholder="Tell AI how to edit (e.g., 'make it shorter', 'add more empathy', 'include troubleshooting steps')"
                      value={aiEditInstructions}
                      onChange={(e) => setAiEditInstructions(e.target.value)}
                      onKeyDown={(e) => {
                        if (e.key === 'Enter' && aiEditInstructions.trim()) {
                          editWithAI();
                        }
                      }}
                      className="flex-1"
                    />
                    <Button
                      variant="secondary"
                      size="sm"
                      onClick={editWithAI}
                      disabled={!aiEditInstructions.trim() || isEditingWithAI}
                    >
                      {isEditingWithAI ? (
                        <Loader2 className="h-4 w-4 animate-spin" />
                      ) : (
                        <Wand2 className="h-4 w-4" />
                      )}
                    </Button>
                  </div>
                )}

                <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-3">
                  <div className="flex items-center gap-2">
                    <Switch
                      id="internal"
                      checked={isInternal}
                      onCheckedChange={setIsInternal}
                    />
                    <Label htmlFor="internal" className="text-sm">
                      Internal note (not visible to user)
                    </Label>
                  </div>
                  <Button onClick={sendResponse} disabled={!newResponse.trim() || isSending}>
                    <Send className="h-4 w-4 mr-2" />
                    Send
                  </Button>
                </div>
              </div>
            </CardContent>
          </Card>
        </div>

        {/* Sidebar */}
        <div className="space-y-6">
          {/* Assignment */}
          <Card>
            <CardHeader>
              <CardTitle className="text-sm font-medium">Assignment</CardTitle>
            </CardHeader>
            <CardContent>
              <TicketAssignment
                assignee={assignee}
                teamMembers={teamMembers}
                collaborators={collaborators}
                isAssigning={isAssigning}
                onAssign={assignTicket}
              />
            </CardContent>
          </Card>

          {/* Status & Priority */}
          <Card>
            <CardHeader>
              <CardTitle className="text-sm font-medium">Ticket Details</CardTitle>
            </CardHeader>
            <CardContent className="space-y-4">
              <div>
                <Label className="text-xs text-muted-foreground">Status</Label>
                <Select
                  value={ticket.status}
                  onValueChange={(value) => updateTicket({ 
                    status: value,
                    resolved_at: value === "resolved" || value === "closed" 
                      ? new Date().toISOString() 
                      : null 
                  })}
                >
                  <SelectTrigger>
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    {STATUS_OPTIONS.map((opt) => (
                      <SelectItem key={opt.value} value={opt.value}>
                        {opt.label}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>

              <div>
                <Label className="text-xs text-muted-foreground">Priority</Label>
                <Select
                  value={ticket.priority}
                  onValueChange={(value) => updateTicket({ priority: value })}
                >
                  <SelectTrigger>
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    {PRIORITY_OPTIONS.map((opt) => (
                      <SelectItem key={opt.value} value={opt.value}>
                        {opt.label}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
            </CardContent>
          </Card>

          {/* Team Notes */}
          <InternalNotesPanel
            notes={internalNotes}
            teamMembers={teamMembers}
            isAddingNote={isAddingNote}
            onAddNote={addInternalNote}
            onDeleteNote={deleteNote}
            parseMentions={parseMentions}
          />

          {/* AI Analysis */}
          <Card>
            <CardHeader className="pb-3">
              <div className="flex items-center justify-between">
                <CardTitle className="text-sm font-medium">AI Analysis</CardTitle>
                <Button
                  variant="ghost"
                  size="sm"
                  onClick={analyzeTicket}
                  disabled={isAnalyzing}
                >
                  {isAnalyzing ? (
                    <Loader2 className="h-4 w-4 animate-spin" />
                  ) : (
                    <RefreshCw className="h-4 w-4" />
                  )}
                </Button>
              </div>
            </CardHeader>
            <CardContent className="space-y-4">
              <div>
                <div className="flex items-center justify-between mb-1">
                  <Label className="text-xs text-muted-foreground">Sentiment</Label>
                  {ticket.sentiment_override && (
                    <Badge variant="outline" className="text-xs">Manual</Badge>
                  )}
                </div>
                <Select
                  value={ticket.sentiment || ""}
                  onValueChange={(value) => updateTicket({ 
                    sentiment: value, 
                    sentiment_override: true 
                  })}
                >
                  <SelectTrigger>
                    <SelectValue placeholder="Not analyzed">
                      {currentSentiment && (
                        <span className={cn("flex items-center gap-2", currentSentiment.color)}>
                          <currentSentiment.icon className="h-4 w-4" />
                          {currentSentiment.label}
                        </span>
                      )}
                    </SelectValue>
                  </SelectTrigger>
                  <SelectContent>
                    {SENTIMENT_OPTIONS.map((opt) => (
                      <SelectItem key={opt.value} value={opt.value}>
                        <span className={cn("flex items-center gap-2", opt.color)}>
                          <opt.icon className="h-4 w-4" />
                          {opt.label}
                        </span>
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>

              <div>
                <div className="flex items-center justify-between mb-1">
                  <Label className="text-xs text-muted-foreground">Urgency</Label>
                  {ticket.urgency_override && (
                    <Badge variant="outline" className="text-xs">Manual</Badge>
                  )}
                </div>
                <Select
                  value={ticket.urgency || ""}
                  onValueChange={(value) => updateTicket({ 
                    urgency: value, 
                    urgency_override: true 
                  })}
                >
                  <SelectTrigger>
                    <SelectValue placeholder="Not analyzed">
                      {currentUrgency && (
                        <span className={cn("flex items-center gap-2", currentUrgency.color)}>
                          <currentUrgency.icon className="h-4 w-4" />
                          {currentUrgency.label}
                        </span>
                      )}
                    </SelectValue>
                  </SelectTrigger>
                  <SelectContent>
                    {URGENCY_OPTIONS.map((opt) => (
                      <SelectItem key={opt.value} value={opt.value}>
                        <span className={cn("flex items-center gap-2", opt.color)}>
                          <opt.icon className="h-4 w-4" />
                          {opt.label}
                        </span>
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>

              {!ticket.sentiment && !ticket.urgency && (
                <Button
                  variant="outline"
                  size="sm"
                  className="w-full"
                  onClick={analyzeTicket}
                  disabled={isAnalyzing}
                >
                  {isAnalyzing ? (
                    <Loader2 className="h-4 w-4 mr-2 animate-spin" />
                  ) : (
                    <Sparkles className="h-4 w-4 mr-2" />
                  )}
                  Analyze Ticket
                </Button>
              )}
            </CardContent>
          </Card>

          {/* Contact Info */}
          <Card>
            <CardHeader>
              <CardTitle className="text-sm font-medium">Contact</CardTitle>
            </CardHeader>
            <CardContent className="space-y-3">
              {ticket.user_id ? (
                <>
                  <div className="flex items-center gap-2 text-sm">
                    <User className="h-4 w-4 text-muted-foreground" />
                    <span>{userProfile?.display_name || "Registered User"}</span>
                  </div>
                  {userProfile?.email && (
                    <div className="flex items-center gap-2 text-sm">
                      <Mail className="h-4 w-4 text-muted-foreground" />
                      <span className="truncate">{userProfile.email}</span>
                    </div>
                  )}
                </>
              ) : ticket.guest_email ? (
                <div className="flex items-center gap-2 text-sm">
                  <Mail className="h-4 w-4 text-muted-foreground" />
                  <span>{ticket.guest_email}</span>
                </div>
              ) : ticket.inbound_email ? (
                <div className="flex items-center gap-2 text-sm">
                  <MailOpen className="h-4 w-4 text-muted-foreground" />
                  <span>{ticket.inbound_email}</span>
                </div>
              ) : (
                <p className="text-sm text-muted-foreground">No contact info</p>
              )}

              {ticket.inbound_email && (
                <Badge variant="outline" className="text-xs">
                  <MailOpen className="h-3 w-3 mr-1" />
                  Created via Email
                </Badge>
              )}

              <div className="flex items-center gap-2 text-sm">
                <Clock className="h-4 w-4 text-muted-foreground" />
                <span>Created {format(new Date(ticket.created_at), "MMM d, yyyy")}</span>
              </div>

              {ticket.resolved_at && (
                <div className="flex items-center gap-2 text-sm text-green-600">
                  <Clock className="h-4 w-4" />
                  <span>Resolved {format(new Date(ticket.resolved_at), "MMM d, yyyy")}</span>
                </div>
              )}

              {/* User History Button */}
              {ticket.user_id && (
                <Sheet open={showUserHistory} onOpenChange={setShowUserHistory}>
                  <SheetTrigger asChild>
                    <Button variant="outline" size="sm" className="w-full mt-2">
                      <History className="h-4 w-4 mr-2" />
                      View Full History
                    </Button>
                  </SheetTrigger>
                  <SheetContent className="w-full sm:max-w-lg overflow-y-auto">
                    <SheetHeader>
                      <SheetTitle>User Support History</SheetTitle>
                    </SheetHeader>
                    <div className="mt-6">
                      <UserSupportActivity 
                        userId={ticket.user_id} 
                        onNavigateAway={() => setShowUserHistory(false)} 
                      />
                    </div>
                  </SheetContent>
                </Sheet>
              )}
            </CardContent>
          </Card>
        </div>
      </div>
    </div>
  );
}
